// Set all fields to initial values.
inline void atf_comp::FEnv_Init(atf_comp::FEnv& parent) {
    parent.had_orig = bool(false);
    parent.set = bool(false);
    parent.ind_env_next = (atf_comp::FEnv*)-1; // (atf_comp.FDb.ind_env) not-in-hash
    parent.ind_env_hashval = 0; // stored hash value
}

